var temp = require('temp');
var test = require('tap').test;
var rimraf = require('rimraf');
var browserify = require('browserify');
var requirify = require('../');
var treenherit = require('../../../packages/mendel-treenherit');
var requireTransform = require('../../../packages/mendel-development/require-transform');

var srcDir = path.resolve(__dirname, '../../../test/app-samples/1');

temp.track();
var buildDir = temp.mkdirSync('build-requirify');

var entry = 'app/number-list.js';
var variationDirs = ['test_A', 'app'];

var mendelRequireRegexp = /__mendel_require__\(/;
var requireRegexp = /\brequire\(/;

function run(t, outDir, outFile, cb) {
    t.plan(4);
    var b = browserify({
        basedir: srcDir,
        entries: [path.join(srcDir, entry)],
    });
    b.transform(treenherit, {
        dirs: variationDirs,
    });
    b.plugin(requirify, {
        outdir: outDir,
        dirs: variationDirs,
    });
    b.bundle(function (err) {
        if (err) {
            t.fail(err.message || err);
        }

        // wait for file to be written
        setTimeout(function () {
            var src;
            try {
                src = fs.readFileSync(outFile, 'utf-8');
            } catch (e) {
                t.fail('Failed to open dest file: ' + outFile);
            }

            t.match(src, mendelRequireRegexp);
            t.notMatch(src, requireRegexp);

            var wrapper = requireTransform.wrapper;
            t.equal(src.indexOf(wrapper[0]), 0, 'wrapper prelude pos');
            t.equal(
                src.indexOf(wrapper[1]),
                src.length - wrapper[1].length,
                'wrapper epilogue pos'
            );

            temp.cleanup(function () {
                if (cb) {
                    return cb(t);
                }
                t.end();
            });
        }, 150);
    });
}

test('mendel-requirify', function (t) {
    var outFile = path.join(buildDir, entry);

    run(t, buildDir, outFile);
});

test('mendel-requirify-defaults', function (t) {
    var outDir = path.join(process.cwd(), 'build-requirify');
    var outFile = path.join(outDir, entry);

    run(t, null, outFile, function (t) {
        rimraf(outDir, function () {
            t.end();
        });
    });
});

const tap = require('tap');
const fs = require('fs');
const os = require('os');
const path = require('path');
const rimraf = require('rimraf');
const browserify = require('browserify');
const requirify = require('../');

const fixtures = path.join(__dirname, 'fixtures');
const entry = path.join(fixtures, 'entry.js');
// entry-skip.js requires no variation-matched module, so bundling it never
// exercises the write path — needed to test the skip branches in isolation.
const entrySkip = path.join(fixtures, 'entry-skip.js');
const dirs = ['variantA'];

let counter = 0;
function tmpOutdir() {
    counter += 1;
    return path.join(
        os.tmpdir(),
        'mendel-requirify-test-' + process.pid + '-' + counter
    );
}

// out.end(...) in index.js has no completion callback, so the write can
// still be in flight when the bundle stream ends; settle before asserting.
function bundle(b) {
    return new Promise((resolve, reject) => {
        const s = b.bundle();
        s.on('error', reject);
        s.resume();
        s.on('end', () => setTimeout(resolve, 200));
    });
}

tap.test(
    'writes a transformed copy of each variation-matched module',
    async (t) => {
        const outdir = tmpOutdir();
        const b = browserify([entry]);
        requirify(b, { outdir, dirs });

        await bundle(b);

        const mainPath = path.join(outdir, 'variantA', 'main.js');
        const helperPath = path.join(outdir, 'variantA', 'helper.js');
        t.ok(fs.existsSync(mainPath), 'writes variantA/main.js');
        t.ok(fs.existsSync(helperPath), 'writes variantA/helper.js');

        const rawSource = fs.readFileSync(
            path.join(fixtures, 'variantA', 'helper.js'),
            'utf8'
        );
        const writtenSource = fs.readFileSync(helperPath, 'utf8');

        t.not(
            writtenSource,
            rawSource,
            'written source differs from the raw fixture source'
        );
