function applyExtraOptions(b, options) {
    []
        .concat(options.ignore)
        .filter(Boolean)
        .forEach(function (i) {
            b._pending++;
            glob(i)
                .then(function (files) {
                    if (files.length === 0) {
                        b.ignore(i);
                    } else {
                        files.forEach(function (file) {
                            b.ignore(file);
                        });
                    }
                    if (--b._pending === 0) b.emit('_ready');
                })
                .catch(function (err) {
                    b.emit('error', err);
                });
        });

    []
        .concat(options.exclude)
        .filter(Boolean)
        .forEach(function (u) {
            b.exclude(u);

            b._pending++;
            glob(u)
                .then(function (files) {
                    files.forEach(function (file) {
                        b.exclude(file);
                    });
                    if (--b._pending === 0) b.emit('_ready');
                })
                .catch(function (err) {
                    b.emit('error', err);
                });
        });

    []
        .concat(options.external)
        .filter(Boolean)
        .forEach(function (x) {
            var xs = splitOnColon(x);
            if (xs.length === 2) {
                add(xs[0], { expose: xs[1] });
            } else if (/\*/.test(x)) {
