class Mendel {
    static get Daemon() {
        return MendelPipelineDaemon;
    }

    static get Client() {
        return MendelClient;
    }

    constructor(config) {
        this.daemon = new Mendel.Daemon(config);
        this.client = new Mendel.Client(
            Object.assign(
                {
                    verbose: false,
                },
                config
            )
        );
    }

    run(callback) {
        this.daemon.run((error) => {
            if (error) {
                if (error instanceof ReferenceError) {
                    console.warn(
                        chalk.yellow(
